import {dessertFamilies,dessertBaseOptions} from './dessert-options.js';
export function initDessertControls({change,getState}){
 const section=document.createElement('section');section.className='control-section dessert-section';
 section.innerHTML='<div class="control-heading"><h3>디저트 발판</h3><span>5종 · 각각 4가지</span></div><p class="panel-note">크림과 과일 장식이 있는 작은 디저트 위에 올라가요. 풀밭 수면에서는 풀밭으로 바뀝니다.</p><button class="clear-accessories" data-dessert-base="none" aria-pressed="true">발판 없이</button>'+dessertFamilies.map(([family,label])=>'<details class="advanced-section" '+(family==='cake'?'open':'')+'><summary>'+label+'<span>4가지</span></summary><div class="model-choice-grid dessert-grid">'+dessertBaseOptions.filter(x=>x.family===family).map(x=>'<button data-dessert-base="'+x.id+'" aria-pressed="false"><img alt="" data-preview="dessert-'+x.id+'"><span>'+x.label+'</span></button>').join('')+'</div></details>').join('')+'<label class="advanced-field range-field"><span>발판 가로 크기<output data-output="dessertBaseScale"></output></span><input data-setting="dessertBaseScale" type="range" min=".7" max="1.5" step=".01" aria-label="발판 가로 크기"></label><label class="advanced-field range-field"><span>발판 높이<output data-output="dessertBaseHeight"></output></span><input data-setting="dessertBaseHeight" type="range" min=".8" max="1.9" step=".01" aria-label="발판 높이"></label>';
 document.querySelector('.accessory-grid').parentElement.insertBefore(section,document.querySelector('.accessory-grid'));
 section.querySelectorAll('[data-dessert-base]').forEach(button=>button.addEventListener('click',()=>change({dessertBase:getState().dessertBase===button.dataset.dessertBase?'none':button.dataset.dessertBase})));
}
export function syncDessertControls(s){document.querySelectorAll('[data-dessert-base]').forEach(button=>{const on=button.dataset.dessertBase===s.dessertBase;button.classList.toggle('selected',on);button.setAttribute('aria-pressed',on);});}
